INSERT INTO match_tactical_changes VALUES(1,55,1,0,12,'0–12′ 좌측 과부하','만잠비가 왼쪽으로 빠지고 음바예가 바깥 — 7′·8′ 서로 슈팅을 만들어 줬다.','reports/match-watch/2026-10-14-avl-fenerbahce.md §2·§3·§4·§7(2026-10-20 백필 · migration 110)','리포트 판정 그대로(백필) — 수치 근거는 원문 표·대조표');
INSERT INTO match_tactical_changes VALUES(2,55,2,12,45,'12′ 코너 선제골 → 전환 득점 2','페네르 빅찬스 3개를 스즈키가 막고, 31′·39′ 전환 득점으로 3-0.','reports/match-watch/2026-10-14-avl-fenerbahce.md §2·§3·§4·§7(2026-10-20 백필 · migration 110)','리포트 판정 그대로(백필) — 수치 근거는 원문 표·대조표');
INSERT INTO match_tactical_changes VALUES(3,55,3,45,73,'후반 블록 하강 · 전환 효율 상승','잭슨 평균 x 85.5 → 63.9m · 캐시 62.3 → 50.3m. 그런데도 후반 xG 2.37.','reports/match-watch/2026-10-14-avl-fenerbahce.md §2·§3·§4·§7(2026-10-20 백필 · migration 110)','리포트 판정 그대로(백필) — 수치 근거는 원문 표·대조표');
INSERT INTO match_tactical_changes VALUES(4,55,4,73,NULL,'73′~ 교체 구조','맥긴 CAM · 알리송 RM · 고메스 RDM → 가르나초 LM(79′) · 아브라함 ST(78′) · 고레츠카 LDM(83′). 빌드업 형태는 유지(표본 LOW).','reports/match-watch/2026-10-14-avl-fenerbahce.md §2·§3·§4·§7(2026-10-20 백필 · migration 110)','리포트 판정 그대로(백필) — 수치 근거는 원문 표·대조표');
INSERT INTO match_tactical_changes VALUES(5,56,1,0,36,'0-0 — 뉴캐슬 고압박','뉴캐슬 def_x 55.3 대 빌라 짧은 빌드업과 전환. 9′ 빅찬스(잭슨) · 28′ 알리송 경고.','reports/match-watch/2026-10-17-avl-newcastle.md §2·§3·§4·§7 + D+2 정정(2026-10-20 백필 · migration 110)','리포트 판정 그대로(백필) — 수치 근거는 원문 표·대조표');
INSERT INTO match_tactical_changes VALUES(6,56,2,36,43,'36′ 만잠비 헤더로 리드','36–46′ 빌라 점유 70% · 뉴캐슬 라인 붕괴(def_x 23.6).','reports/match-watch/2026-10-17-avl-newcastle.md §2·§3·§4·§7 + D+2 정정(2026-10-20 백필 · migration 110)','리포트 판정 그대로(백필) — 수치 근거는 원문 표·대조표');
INSERT INTO match_tactical_changes VALUES(7,56,3,43,56,'43′ 뉴캐슬 압박 전환 · 46′ 알리송→맥긴','스즈키 직접 배급으로 전환. 알리송 교체는 경고 관리(주) + 부하 관리(배경).','reports/match-watch/2026-10-17-avl-newcastle.md §2·§3·§4·§7 + D+2 정정(2026-10-20 백필 · migration 110)','리포트 판정 그대로(백필) — 수치 근거는 원문 표·대조표');
INSERT INTO match_tactical_changes VALUES(8,56,4,56,72,'56′ 뉴캐슬 교체 2 → 압박 정점','56–77′ PPDA 4.89 · 빌라 자기 진영 패스 성공률 67%.','reports/match-watch/2026-10-17-avl-newcastle.md §2·§3·§4·§7 + D+2 정정(2026-10-20 백필 · migration 110)','리포트 판정 그대로(백필) — 수치 근거는 원문 표·대조표');
INSERT INTO match_tactical_changes VALUES(9,56,5,72,77,'72′ 빌라 3명 교체','바클리 CAM · 음바예 LM(인사이드 포워드 기하) · 고레츠카 LDM.','reports/match-watch/2026-10-17-avl-newcastle.md §2·§3·§4·§7 + D+2 정정(2026-10-20 백필 · migration 110)','리포트 판정 그대로(백필) — 수치 근거는 원문 표·대조표');
INSERT INTO match_tactical_changes VALUES(10,56,6,77,NULL,'77′ 완비사카 부상 → 저블록','토레스 LCB · 밍스 LB. 스즈키 롱 11/12 · 린델뢰프·고레츠카 클리어 9 · 음바예 역습 슈팅 3.','reports/match-watch/2026-10-17-avl-newcastle.md §2·§3·§4·§7 + D+2 정정(2026-10-20 백필 · migration 110)','리포트 판정 그대로(백필) — 수치 근거는 원문 표·대조표');
INSERT INTO match_tactical_changes VALUES(11,62,1,0,23,'0-0 — 양 팀 중간·높은 압박','빌라 PPDA 7.5·def_x 41.2 · 바이킹 def_x 45.6. 바클리 전진(x 66) · 잭슨 3′·6′ 헤더 선방 · 22′ 고메스 크로스 크로스바 → 23′ 바클리 코너 헤더.','reports/match-watch/2026-10-21-avl-viking.md 요약·사용자 의견 대조표·§2~§7 (2026-10-22 09:00 회차)','리포트 판정 그대로 — 근거는 각 행 evidence(WS 2029164 · SS 16938853 · FM 6106285 · 커널 FC27)');
INSERT INTO match_tactical_changes VALUES(12,62,2,23,45,'리드 — 바이킹 로우블록','바이킹 def_x 35.0 · 빌라 전반 점유 66%. 잭슨 좌측 벌리기(20–40′). 33~37′ 알리송 PK 획득(VAR) → 37′ 부엔디아 2-0. 전반 xG 1.95–0.02.','reports/match-watch/2026-10-21-avl-viking.md 요약·사용자 의견 대조표·§2~§7 (2026-10-22 09:00 회차)','리포트 판정 그대로 — 근거는 각 행 evidence(WS 2029164 · SS 16938853 · FM 6106285 · 커널 FC27)');
INSERT INTO match_tactical_changes VALUES(13,62,3,45,62,'후반 점유 하락','빌라 PPDA 15.6 · 부엔디아 하강(x 56.5). 55′ 부엔디아·57′ 알리송 슈팅.','reports/match-watch/2026-10-21-avl-viking.md 요약·사용자 의견 대조표·§2~§7 (2026-10-22 09:00 회차)','리포트 판정 그대로 — 근거는 각 행 evidence(WS 2029164 · SS 16938853 · FM 6106285 · 커널 FC27)');
INSERT INTO match_tactical_changes VALUES(14,62,4,62,70,'62′ 자책골 3-0 · 내려앉기','알리송 크로스 → 헤그헤임 자책. 빌라 def_x 26.7(최저 구간).','reports/match-watch/2026-10-21-avl-viking.md 요약·사용자 의견 대조표·§2~§7 (2026-10-22 09:00 회차)','리포트 판정 그대로 — 근거는 각 행 evidence(WS 2029164 · SS 16938853 · FM 6106285 · 커널 FC27)');
INSERT INTO match_tactical_changes VALUES(15,62,5,70,84,'70′ 3명 교체 + 72′ 가르나초 — 4백 복귀','고메스→캐시(전문 RB) · 잭슨→에이브러햄 · 바클리→고레츠카 · 음바예→가르나초 · 75′ 알리송→헤밍스. AVR 「more of a back four」(백4에 더 가까운). 가르나초 78·81·88′ 슈팅.','reports/match-watch/2026-10-21-avl-viking.md 요약·사용자 의견 대조표·§2~§7 (2026-10-22 09:00 회차)','리포트 판정 그대로 — 근거는 각 행 evidence(WS 2029164 · SS 16938853 · FM 6106285 · 커널 FC27)');
INSERT INTO match_tactical_changes VALUES(16,62,6,84,NULL,'84′ 실점 3-1','크리스티안센(아스킬센 도움) — 기사는 오프사이드 취소 → VAR 인정. SS는 86′ 아스킬센 goalNotAwarded로 기록(충돌 · D+2 확정).','reports/match-watch/2026-10-21-avl-viking.md 요약·사용자 의견 대조표·§2~§7 (2026-10-22 09:00 회차)','리포트 판정 그대로 — 근거는 각 행 evidence(WS 2029164 · SS 16938853 · FM 6106285 · 커널 FC27)');
